class ProxyStream:
    def __getattr__(self, name):
        if name == "read":
            return lambda size=-1: b"proxy data"
        raise AttributeError(name)

def test_proxy_stream_content_type():
    req = Request("POST", "http://httpbin.org/post", data=ProxyStream())
    prep = req.prepare()
    print(f"Content-Type: {prep.headers.get("Content-Type")}")
    assert prep.headers.get("Content-Type") != "application/x-www-form-urlencoded"

if __name__ == "__main__":
